/// Scoped DAP channel membership (issue #1825): one record shape for all
/// three scopes, and the union/dedup algebra the delivery layer rides on.
///
/// Scopes are blast-radius controls, widest last:
/// - [DapChannelScope.session] — a `dap_channel_membership` custom record
///   on the session JSONL tree (re-join on resume, dies with the branch);
/// - [DapChannelScope.project] — `.fah/dap.json` in the project root;
/// - [DapChannelScope.global] — the machine-wide `~/.dap` channel list.
///
/// Effective membership is the union deduped by `(hubUrl, channelId)`: the
/// same channel joined at two scopes delivers each frame ONCE, and leaving
/// one scope keeps the other alive.
library;

/// The three membership scopes, ordered narrowest → widest.
enum DapChannelScope { session, project, global }

/// One channel membership record. [pub]/[priv] are the channel X25519
/// keypair (base64) — null for a PUBLIC channel (keyless join).
///
/// At rest, [priv] may hold a `dapkey1.` passphrase-encrypted envelope
/// instead of plaintext (see `dap_key_envelope.dart`); the delivery layer
/// only ever sees the decrypted form in memory.
final class DapChannelMembership {
  const DapChannelMembership({
    required this.hubUrl,
    required this.channelId,
    required this.scope,
    required this.joinedAt,
    this.pub,
    this.priv,
    this.agentName,
    this.hubClientSecret,
  });

  /// The hub this channel lives on — per-channel, so an invite for a
  /// DIFFERENT hub never clobbers the default hub config (E3).
  final String hubUrl;

  /// The channel id (no leading `#`).
  final String channelId;

  /// Where this membership is stored / how far it reaches.
  final DapChannelScope scope;

  /// Join time (UTC) — informational, stable across resumes.
  final DateTime joinedAt;

  /// Channel public key (base64), when the channel is private.
  final String? pub;

  /// Channel private key (base64 plaintext in memory, or a `dapkey1.`
  /// envelope at rest).
  final String? priv;

  /// The enrolled agent display name the hub credential is bound to
  /// (the app's DAP enrollment mints name-bound secrets).
  final String? agentName;

  /// The hub-issued client secret for [hubUrl] — REQUIRED on hubs that
  /// reject the machine's default credential (a secret enrolled on one
  /// hub is not valid on another). At rest a `dapkey1.` envelope, like
  /// [priv]; never serialized in plaintext for session/project scopes.
  final String? hubClientSecret;

  /// The dedup identity: same hub + same channel = same membership,
  /// regardless of scope.
  String get key => '$hubUrl\n$channelId';

  DapChannelMembership withScope(DapChannelScope newScope) =>
      DapChannelMembership(
        hubUrl: hubUrl,
        channelId: channelId,
        scope: newScope,
        joinedAt: joinedAt,
        pub: pub,
        priv: priv,
        agentName: agentName,
        hubClientSecret: hubClientSecret,
      );

  /// Serializes for the session record / project store. Secrets handling
  /// (encryption of [priv]) is the store's job, not the record's.
  Map<String, Object?> toJson() => {
    'hubUrl': hubUrl,
    'channelId': channelId,
    'scope': scope.name,
    'joinedAt': joinedAt.toUtc().toIso8601String(),
    if (pub != null) 'pub': pub,
    if (priv != null) 'priv': priv,
    if (agentName != null) 'agentName': agentName,
    if (hubClientSecret != null) 'hubClientSecret': hubClientSecret,
  };

  /// Tolerant reader: unknown scope values fall back to null (caller
  /// skips), malformed records throw [FormatException] so a corrupted
  /// store fails loudly instead of silently dropping memberships.
  static DapChannelMembership fromJson(Map<String, Object?> json) {
    final hubUrl = json['hubUrl'];
    final channelId = json['channelId'];
    final scopeName = json['scope'];
    if (hubUrl is! String || hubUrl.isEmpty) {
      throw const FormatException('membership: missing hubUrl');
    }
    if (channelId is! String || channelId.isEmpty) {
      throw const FormatException('membership: missing channelId');
    }
    final scope = DapChannelScope.values.where((s) => s.name == scopeName);
    if (scope.isEmpty) {
      throw FormatException('membership: unknown scope "$scopeName"');
    }
    final joinedAtRaw = json['joinedAt'];
    final joinedAt = joinedAtRaw is String
        ? DateTime.tryParse(joinedAtRaw)
        : null;
    return DapChannelMembership(
      hubUrl: hubUrl,
      channelId: channelId,
      scope: scope.first,
      joinedAt: joinedAt ?? DateTime.fromMillisecondsSinceEpoch(0, isUtc: true),
      pub: json['pub'] as String?,
      priv: json['priv'] as String?,
      agentName: json['agentName'] as String?,
      hubClientSecret: json['hubClientSecret'] as String?,
    );
  }
}

/// The union of all scope stores, deduped by `(hubUrl, channelId)`.
///
/// Precedence on conflict: session > project > global — the NARROWEST
/// scope wins the key material, so a session join with fresh invite keys
/// cannot be shadowed by a stale global entry. Delivery dedups by [key]
/// either way; the scope badges list every scope a channel is joined at.
final class DapMembershipUnion {
  DapMembershipUnion(Iterable<DapChannelMembership> memberships) {
    for (final m in memberships) {
      _byKey.putIfAbsent(m.key, () => []).add(m);
    }
  }

  final Map<String, List<DapChannelMembership>> _byKey = {};

  static const _precedence = [
    DapChannelScope.session,
    DapChannelScope.project,
    DapChannelScope.global,
  ];

  /// One effective membership per `(hubUrl, channelId)`, narrowest scope
  /// winning the key material.
  List<DapChannelMembership> effective() {
    final out = <DapChannelMembership>[];
    for (final entry in _byKey.entries) {
      final candidates = entry.value;
      candidates.sort(
        (a, b) => _precedence
            .indexOf(a.scope)
            .compareTo(_precedence.indexOf(b.scope)),
      );
      out.add(candidates.first);
    }
    out.sort((a, b) => a.key.compareTo(b.key));
    return out;
  }

  /// Every scope a given channel is joined at (for the `/network` badges).
  List<DapChannelScope> scopesOf(String hubUrl, String channelId) {
    final key = '$hubUrl\n$channelId';
    final candidates = _byKey[key] ?? const [];
    final scopes = candidates.map((m) => m.scope).toSet();
    return [
      for (final s in _precedence)
        if (scopes.contains(s)) s,
    ];
  }

  /// The union that remains after leaving `(hubUrl, channelId)` at
  /// [scope] — other scopes keep the channel alive (E1).
  DapMembershipUnion leaving(
    String hubUrl,
    String channelId,
    DapChannelScope scope,
  ) {
    final key = '$hubUrl\n$channelId';
    return DapMembershipUnion([
      for (final entry in _byKey.entries)
        for (final m in entry.value)
          if (!(entry.key == key && m.scope == scope)) m,
    ]);
  }
}

import 'dart:async';
import 'dart:convert';
import 'dart:io';

import 'package:cryptography/cryptography.dart';
import 'package:fa_hub_client/fa_hub_client.dart'
    hide AgentMessage, MailboxEntry;
import 'package:flutter_agent_harness/flutter_agent_harness.dart'
    hide HubIdentity, PluginContext;
import 'package:test/test.dart';

import '../../bin/hub_fabric_repository.dart';
import 'fake_hub.dart';

const timeout = Timeout(Duration(seconds: 10));

void main() {
  late FakeHub hub;
  late HubClient sender;

  setUp(() async {
    hub = FakeHub();
    await hub.start();
    sender = HubClient(
      config: HubConfig(url: hub.url.toString()),
      identity: await HubIdentity.generate(),
    );
    await sender.connect();
  });

  tearDown(() async {
    await sender.disconnect();
    await hub.stop();
  });

  /// A plugin started against [hub], the adapter over it.
  Future<(HubFabricRepository, HubPlugin)> newFabric() async {
    final tmp = await Directory.systemTemp.createTemp('fah-hub-fabric');
    addTearDown(() => tmp.delete(recursive: true));
    final plugin = HubPlugin(
      environment: const {'DAP_MASTER_SECRET': 'test-master'},
    );
    plugin.register(
      PluginContext(
        config: {
          'hub': {
            'url': hub.url.toString(),
            'keyPath': '${tmp.path}/hub-key',
            'name': 'fabric-probe',
          },
        },
      ),
    );
    await plugin.start();
    addTearDown(plugin.dispose);
    return (HubFabricRepository(plugin), plugin);
  }

  test('outbound fabric mail rides the hub as the sender identity', () async {
    final (adapter, plugin) = await newFabric();
    final arrived = sender.inbound
        .firstWhere((m) => m.plaintext == 'ping')
        .timeout(const Duration(seconds: 5));
    await adapter.send(
      AgentMessage(
        id: 'm1',
        fromId: 'main',
        toId: sender.agentId!,
        text: 'ping',
        sentAt: DateTime.now().toUtc().toIso8601String(),
      ),
    );
    final message = await arrived;
    expect(message.from, plugin.agentId);
  }, timeout: timeout);

  test(
    'inbound hub mail drains through the fabric with sender attribution',
    () async {
      final (adapter, plugin) = await newFabric();
      final arrived = plugin.repository!.client.inbound
          .firstWhere((m) => m.plaintext == 'wake')
          .timeout(const Duration(seconds: 5));
      await sender.sendDm(plugin.agentId!, 'wake');
      await arrived;
      final drained = await adapter.drain('main');
      expect(drained, hasLength(1));
      expect(drained.single.text, 'wake');
      expect(drained.single.fromId, sender.agentId);
      expect(drained.single.toId, plugin.agentId);
      expect(DateTime.parse(drained.single.sentAt).isUtc, isTrue);
      // Drained mail is gone.
      expect(await adapter.drain('main'), isEmpty);
      await sender.sendDm(plugin.agentId!, 'again');
      await plugin.repository!.client.inbound
          .firstWhere((m) => m.plaintext == 'again')
          .timeout(const Duration(seconds: 5));
      final peeked = await adapter.peek('main');
      expect(peeked.single.text, 'again');
      expect(await adapter.drain('main'), hasLength(1));
    },
    timeout: timeout,
  );

  test('PUBLIC channel: fabric sends the raw base64({"text":…}) contract, '
      'keyless members decode it, and #channel inboxes drain', () async {
    final (adapter, plugin) = await newFabric();
    final fabric = HubFabricRepository(
      plugin,
      publicChannelChecker: (_, channel) async => channel == 'room',
      channelLister: (_) async => ['room'],
    );
    // Keyless joins on both ends (the public showcase membership).
    plugin.repository!.client.join('room', '');
    sender.join('room', '');

    // Fabric → sender: the payload is the public contract, decoded by
    // a keyless client (no "undecryptable" placeholder).
    final arrived = sender.inbound
        .firstWhere((m) => m.channel == 'room')
        .timeout(const Duration(seconds: 5));
    await fabric.send(
      AgentMessage(
        id: 'pub1',
        fromId: 'main',
        toId: '#room',
        text: 'hello public',
        sentAt: DateTime.now().toUtc().toIso8601String(),
      ),
    );
    expect((await arrived).plaintext, 'hello public');

    // Sender → fabric: the #room inbox is drained ALONGSIDE the agent
    // inbox (drain(agentId) alone drops channel traffic).
    final received = plugin.repository!.client.inbound
        .firstWhere((m) => m.channel == 'room')
        .timeout(const Duration(seconds: 5));
    await sender.sendChannelEnvelope(
      'room',
      (frameId) async => encodePublicChannelText('back at you'),
    );
    await received;
    final drained = await fabric.drain('main');
    expect(drained, hasLength(1));
    expect(drained.single.toId, '#room');
    expect(drained.single.text, 'back at you');
    expect(drained.single.fromId, sender.agentId);
  }, timeout: timeout);

  test('a private channel with an UNRESOLVED key refuses loudly instead '
      'of downgrading to plaintext or auto-keygen (gh-1888 review)', () async {
    final (adapter, plugin) = await newFabric();
    final fabric = HubFabricRepository(
      plugin,
      privateKeyMissingChecker: (_, channel) async => channel == 'locked',
    );
    await expectLater(
      fabric.send(
        AgentMessage(
          id: 'blk1',
          fromId: 'main',
          toId: '#locked',
          text: 'secret payload',
          sentAt: DateTime.now().toUtc().toIso8601String(),
        ),
      ),
      throwsA(
        isA<StateError>().having(
          (e) => e.message,
          'message',
          allOf(contains('refusing to send to #locked'), contains('key')),
        ),
      ),
    );
    // Nothing reached the wire.
    await expectLater(
      sender.inbound
          .firstWhere((m) => m.channel == 'locked')
          .timeout(const Duration(milliseconds: 300)),
      throwsA(anything),
    );
  }, timeout: timeout);

  test('PRIVATE channel: fabric sends a fanet1 frame, not RAW dap/1', () async {
    final (adapter, plugin) = await newFabric();
    const channel = 'private-room';
    final keys = await newChannelKeypair();
    final client = plugin.repository!.client;
    await client.channelStore!.accept(channel, keys);
    client.join(channel, keys.pub);
    sender.join(channel, keys.pub);

    final arrived = sender.inbound
        .firstWhere((message) => message.channel == channel)
        .timeout(const Duration(seconds: 5));
    await adapter.send(
      AgentMessage(
        id: 'private1',
        fromId: 'main',
        toId: '#$channel',
        text: 'hello private',
        sentAt: DateTime.now().toUtc().toIso8601String(),
      ),
    );
    await arrived;

    final wire = hub.relayed.single;
    final payload = base64Decode(wire['ciphertext'] as String);
    expect(payload.first, fanet1FrameVersion);
    expect(payload.sublist(1, 33), client.identity.dhPublicKey.bytes);
    expect(
      payload.length,
      1 + 32 + 12 + 16 + utf8.encode('hello private').length,
    );
    final opened = await openFanet1(
      channelKeyPair: await X25519().newKeyPairFromSeed(
        base64Decode(keys.priv),
      ),
      frameId: wire['id'] as String,
      channelId: channel,
      payloadB64: wire['ciphertext'] as String,
    );
    expect(opened.plaintext, 'hello private');
  }, timeout: timeout);

  test('resolveTarget answers the roster; channels pass through', () async {
    final (adapter, plugin) = await newFabric();
    expect(await adapter.resolveTarget(sender.agentId!), sender.agentId);
    expect(await adapter.resolveTarget('fabric-probe'), plugin.agentId);
    expect(await adapter.resolveTarget('#general'), '#general');
    // Our own hub id is not a fabric target (the file mailbox owns it).
    expect(await adapter.resolveTarget(plugin.agentId!), isNull);
    expect(adapter.isConnected, isTrue);
  }, timeout: timeout);

  test('directory maps the hub roster onto mailbox entries', () async {
    final (adapter, plugin) = await newFabric();
    final entries = await adapter.directory();
    final ids = entries.map((e) => e.id);
    expect(ids, containsAll([sender.agentId, plugin.agentId]));
    expect(entries.firstWhere((e) => e.id == sender.agentId).id, isNotNull);
    // Registration-backed presence: every connected roster peer is live —
    // no mtime heuristic.
    expect(entries.map((e) => e.presence), everyElement(AgentPresence.live));
    // Hub roster entries carry no capabilities (not on the wire yet).
    expect(
      entries.firstWhere((e) => e.id == sender.agentId).capabilities,
      isEmpty,
    );
  }, timeout: timeout);

  test('directory falls back to empty when the hub drops mid-query', () async {
    final (adapter, plugin) = await newFabric();
    expect(plugin.agentId, isNotNull);
    // Simulate the hub being gone: presenceQuery's waiter is failed with
    // StateError('connection closed') — the directory must degrade to an
    // empty roster (the composite falls back to the file fabric), never
    // throw into a background poller.
    await hub.stop();
    await Future<void>.delayed(const Duration(milliseconds: 100));
    expect(await adapter.directory(), isEmpty);
  }, timeout: timeout);

  test('the adapter serves exactly one inbox — the hub identity\'s; the '
      'COMPOSITE guards which fabric mailbox reaches it', () async {
    final (adapter, plugin) = await newFabric();
    final arrived = plugin.repository!.client.inbound
        .firstWhere((m) => m.plaintext == 'wake')
        .timeout(const Duration(seconds: 5));
    await sender.sendDm(plugin.agentId!, 'wake');
    await arrived;
    // The adapter maps every drain to the hub inbox; the
    // FallbackMessagingRepository (tested separately) is what keeps
    // subagent mailboxes away from it.
    expect(await adapter.drain('sub1'), hasLength(1));
    // register/touch are deliberate no-ops.
    await adapter.register('main', sessionName: 'goal_builder');
    await adapter.touch('main');
  }, timeout: timeout);

  test('disconnected adapter resolves nothing and reads empty', () async {
    final (adapter, plugin) = await newFabric();
    // Simulate the hub being gone: stop it under the plugin.
    await hub.stop();
    await Future<void>.delayed(const Duration(milliseconds: 100));
    // The send contract throws honestly when the hub is unreachable.
    await expectLater(
      adapter.send(
        AgentMessage(
          id: 'm2',
          fromId: 'main',
          toId: sender.agentId!,
          text: 'lost',
          sentAt: DateTime.now().toUtc().toIso8601String(),
        ),
      ),
      throwsStateError,
    );
    expect(adapter.isConnected, anyOf(isTrue, isFalse)); // never throws
    expect(plugin.agentId, isNotNull);
  }, timeout: timeout);
}

