    final params = Uri.splitQueryString(uri.fragment);
    pub = _keyParam(params, 'pub');
    priv = _keyParam(params, 'priv');
  }
  return DapInviteImport(
    hubUrl: uri.removeFragment().toString(),
    channel: channel,
    pub: pub,
    priv: priv,
  );
